    return write_all(fd, &h, sizeof h) == 0 ? STORE_OK : STORE_ERR_IO;
}

/* Every check has to pass. If one fails this is not our file, and we
 * refuse to touch it: it could be somebody else's data. */
static enum store_status check_header(int fd, off_t size)
{
    struct dsm_store_header h;
    if (size < (off_t)sizeof h)
        return STORE_ERR_FORMAT;
    if (pread(fd, &h, sizeof h, 0) != (ssize_t)sizeof h)
        return STORE_ERR_IO;
    if (memcmp(h.magic, DSM_STORE_MAGIC, sizeof h.magic) != 0
        || h.crc32 != header_crc(&h)
        || h.schema_ver != DSM_SCHEMA_VER
        || h.record_size != sizeof(struct dsm_record))
        return STORE_ERR_FORMAT;
    return STORE_OK;
}

/* Find where the good records end, and cut off everything after that.
 * A crash in the middle of a write leaves part of a record, or a block of
 * zeros, at the end of the file. We keep every record up to the first one
 * that is short or fails its CRC, and drop the rest. */
static enum store_status recover(int fd, off_t size, struct store_recovery *out)
{
    const off_t rec_size = (off_t)sizeof(struct dsm_record);
    off_t end = (off_t)sizeof(struct dsm_store_header);   /* end of the good part */
    uint64_t kept = 0;
    struct dsm_record r;

    while (size - end >= rec_size) {
        ssize_t n = pread(fd, &r, sizeof r, end);
        if (n < 0)
            return STORE_ERR_IO;   /* a failed read is not a bad record: cut nothing */
        if (n != rec_size || !record_intact(&r))
            break;
        kept++;
        end += rec_size;
    }

    out->kept = kept;
    out->cut_bytes = (uint64_t)(size - end);
    if (end == size)
        return STORE_OK;           /* clean: don't touch the file at all */

    /* fsync so the cut itself is on the card before anything new is
     * appended after it. */
    if (ftruncate(fd, end) != 0 || fsync(fd) != 0)
        return STORE_ERR_IO;
    return STORE_OK;
}

enum store_status store_open(const char *path, struct dsm_store **out)
{
    enum store_status st;
    struct dsm_store *s = NULL;
    struct store_recovery rec = {0, 0};
    struct stat sb;
    int saved_errno;

    *out = NULL;

    /* O_APPEND: every write goes to the current end of the file.
     * O_CLOEXEC: the fd is closed automatically if this process execs
     * another program, so it can't leak into children. */
    int fd = open(path, O_RDWR | O_CREAT | O_APPEND | O_CLOEXEC, 0644);
    if (fd < 0)
        return STORE_ERR_IO;

    if (fstat(fd, &sb) != 0) {
        st = STORE_ERR_IO;
        goto fail;
    }

    /* Empty means we just created it (or a crash came before the header
     * was written), so it gets a header. Otherwise it must already be ours,
     * and only then is it safe to cut anything off its end. */
    if (sb.st_size == 0) {
        st = write_header(fd);
    } else {
        st = check_header(fd, sb.st_size);
        if (st == STORE_OK)
            st = recover(fd, sb.st_size, &rec);
    }
    if (st != STORE_OK)
        goto fail;

    s = malloc(sizeof *s);
    if (s == NULL) {
        st = STORE_ERR_IO;     /* errno is ENOMEM */
        goto fail;
    }
    s->fd = fd;
    s->broken = false;
    s->recovery = rec;
    *out = s;
    return STORE_OK;

fail:
    saved_errno = errno;       /* close() could overwrite the real reason */
    close(fd);
    errno = saved_errno;
    return st;
}

enum store_status store_append(struct dsm_store *s, const struct dsm_record *r)
{
    if (s->broken)
        return STORE_ERR_BROKEN;

    /* Recovery will cut the file off at the first bad record, so one bad
     * record let in here would cost every good record after it. */
    if (!record_intact(r))
        return STORE_ERR_BADREC;

    /* If this fails part-way, part of a record may now be on disk, and
     * anything appended after it would be misaligned. Stop here instead. */
    if (write_all(s->fd, r, sizeof *r) != 0) {
        s->broken = true;
        return STORE_ERR_IO;
    }
    return STORE_OK;
}

/* Accepts NULL, like free(), so cleanup code can call it unconditionally. */
enum store_status store_close(struct dsm_store *s)
{
    if (s == NULL)
        return STORE_OK;
    int rc = close(s->fd);
    free(s);
    return rc == 0 ? STORE_OK : STORE_ERR_IO;
}

struct store_recovery store_get_recovery(const struct dsm_store *s)
{
    return s->recovery;
}

SRC  := $(COMMON_SRC) $(STORE_SRC) $(SENSOR_SRC)
TSRC := tests/test_main.c $(COMMON_TSRC) $(STORE_TSRC) $(SENSOR_TSRC)
HDR  := tests/check.h tests/suites.h $(COMMON_HDR) $(STORE_HDR) $(SENSOR_HDR)

TESTBIN := build/test_all

## all: build the test binary
all: $(TESTBIN)

$(TESTBIN): $(SRC) $(TSRC) $(HDR)
	@mkdir -p build
	$(CC) $(CFLAGS) $(SRC) $(TSRC) -o $@

## test: run every test suite
test: $(TESTBIN)
	./$(TESTBIN)

## asan: rebuild with AddressSanitizer + UBSan and run the tests
asan: CFLAGS += $(SANFLAGS)
asan: clean test

## memcheck: run the tests under valgrind (Linux/Pi only, not on macOS)
memcheck: all
	@if ! command -v valgrind >/dev/null 2>&1; then \
	    echo "make memcheck: valgrind not installed here (expected on macOS - run this on the Pi)."; \
	  else \
	    valgrind --leak-check=full --show-leak-kinds=all --error-exitcode=1 ./$(TESTBIN); \
	  fi

## soakcheck: 1-hour miniature of the graded 48h soak
soakcheck:
	@echo "make soakcheck: not implemented yet - needs the supervisor and heartbeat logging."
	@echo "Per spec 3.4 this must exercise: startup, hourly heartbeat (liveness/RSS/event counts),"
	@echo "an injected fault with detect-degrade-recover, and an orderly shutdown."

## deploy: rsync the tree to the Pi. usage: make deploy PI=pi@hostname
deploy:
	@if [ -z "$(PI)" ]; then \
	    echo "usage: make deploy PI=pi@hostname"; exit 1; \
	  else \
	    rsync -av --exclude '.git' --exclude 'build' --exclude 'transcripts' ./ $(PI):~/term-project/; \
	  fi

## clean: remove build artifacts
clean:
	rm -rf build

## help: list targets
help:
	@grep -E '^## ' $(MAKEFILE_LIST) | sed 's/^## /  /'

.PHONY: all test asan memcheck soakcheck deploy clean help
#include "common/log.h"

#include <stdarg.h>
#include <string.h>
#include <time.h>
#include <unistd.h>

enum { LINE_MAX_BYTES = 512 };

static const char *log_proc = "?";
static FILE *log_out;          /* NULL means stderr */

void log_init(const char *proc, FILE *out)
{
    log_proc = proc;
    log_out = out;
    tzset();                   /* so localtime_r uses this machine's time zone */
}

static const char *level_name(enum log_level lvl)
{
    switch (lvl) {
    case LVL_INFO:  return "INFO";
    case LVL_WARN:  return "WARN";
    case LVL_ERROR: return "ERROR";
    }
    return "?";
}

/* Add to the line. If it doesn't fit, it is cut short. One byte is always
 * left free for the '\n'. */
static void vadd(char *line, size_t *len, const char *fmt, va_list ap)
{
    size_t room = LINE_MAX_BYTES - 1 - *len;   /* includes vsnprintf's '\0' */
    int w = vsnprintf(line + *len, room, fmt, ap);
    if (w < 0)
        return;
    *len += (size_t)w < room ? (size_t)w : room - 1;
}

static void add(char *line, size_t *len, const char *fmt, ...)
{
    va_list ap;
    va_start(ap, fmt);
    vadd(line, len, fmt, ap);
    va_end(ap);
}

void log_msg(enum log_level lvl, const char *event, const char *fmt, ...)
{
    char line[LINE_MAX_BYTES];
    size_t len = 0;
    struct timespec real = {0, 0}, mono = {0, 0};
    struct tm tm;

    clock_gettime(CLOCK_REALTIME, &real);
    clock_gettime(CLOCK_MONOTONIC, &mono);

    if (localtime_r(&real.tv_sec, &tm) != NULL)
        len = strftime(line, sizeof line - 1, "%Y-%m-%dT%H:%M:%S%z", &tm);
    if (len == 0)
        add(line, &len, "0000-00-00T00:00:00+0000");   /* time unknown */

    add(line, &len, " %lld.%03ld %s[%ld] %s %s",
        (long long)mono.tv_sec, mono.tv_nsec / 1000000L,
        log_proc, (long)getpid(), level_name(lvl), event);

    if (fmt != NULL) {
        va_list ap;
        add(line, &len, " ");
        va_start(ap, fmt);
        vadd(line, &len, fmt, ap);
        va_end(ap);
    }
    line[len++] = '\n';

    /* The whole line is built first and written with one call, so it isn't
     * split into pieces the way several fprintf calls could split it. */
    FILE *out = log_out != NULL ? log_out : stderr;
    fwrite(line, 1, len, out);
    fflush(out);
}
